class Solution:
    def longestCommonPrefix(self, arr1: List[int], arr2: List[int]) -> int:
        prefixes = set()
        for x in arr1:
            s = str(x)
            for i in range(1, len(s) + 1):
                prefixes.add(s[:i])

        best = 0
        for y in arr2:
            s = str(y)
            # check from longest prefix to shortest
            for i in range(len(s), best, -1):
                if s[:i] in prefixes:
                    best = i
                    break
        return best
