class Solution:
    def longestCommonPrefix(self, arr1: List[int], arr2: List[int]) -> int:
        prefixes = set()
        for num in arr1:
            p = num
            while p > 0:
                prefixes.add(p)
                p //= 10

        best = 0
        for num in arr2:
            p = num
            while p > 0:
                if p in prefixes:
                    length = len(str(p))
                    if length > best:
                        best = length
                    break
                p //= 10
        return best
