import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    value = st.one_of(
        st.integers(1, 20),
        st.integers(1, 1000),
        st.integers(1, 10**8),
        st.sampled_from([1, 10, 100, 1000, 10**4, 10**7, 10**8, 12, 123, 1234]),
    )
    arr1 = draw(st.lists(value, min_size=1, max_size=6))
    arr2 = draw(st.lists(value, min_size=1, max_size=6))
    if draw(st.booleans()):
        # force some shared prefixes by deriving from arr1 elements
        extra = []
        for x in arr1[:3]:
            s = str(x)
            k = draw(st.integers(1, len(s)))
            cand = int(s[:k] + str(draw(st.integers(0, 9))) * draw(st.integers(0, 2)))
            if 1 <= cand <= 10**8:
                extra.append(cand)
        if extra:
            arr2 = (arr2 + extra)[:6]
    return f"{json.dumps(arr1)}\n{json.dumps(arr2)}"

def _is_int_list(v):
    return isinstance(v, list) and 1 <= len(v) <= 5 * 10**4 and all(
        isinstance(x, int) and not isinstance(x, bool) and 1 <= x <= 10**8 for x in v
    )

def validate(inp):
    try:
        lines = inp.split("\n")
        if len(lines) != 2:
            return False
        a = json.loads(lines[0])
        b = json.loads(lines[1])
    except Exception:
        return False
    return _is_int_list(a) and _is_int_list(b)

def ref(inp):
    lines = inp.split("\n")
    arr1 = json.loads(lines[0])
    arr2 = json.loads(lines[1])
    best = 0
    for x in arr1:
        sx = str(x)
        for y in arr2:
            sy = str(y)
            k = 0
            while k < min(len(sx), len(sy)) and sx[k] == sy[k]:
                k += 1
            if k > best:
                best = k
    return json.dumps(best)
