import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    kind = draw(st.integers(0, 4))
    if kind == 0:
        # small values with many shared prefixes
        arr1 = draw(st.lists(st.integers(1, 1000), min_size=1, max_size=6))
        arr2 = draw(st.lists(st.integers(1, 1000), min_size=1, max_size=6))
    elif kind == 1:
        # all equal elements
        v1 = draw(st.integers(1, 10**8))
        v2 = draw(st.integers(1, 10**8))
        arr1 = [v1] * draw(st.integers(1, 4))
        arr2 = [v2] * draw(st.integers(1, 4))
    elif kind == 2:
        # extremes of the range
        pool = [1, 2, 9, 10, 99, 100, 10**8, 10**8 - 1]
        arr1 = draw(st.lists(st.sampled_from(pool), min_size=1, max_size=5))
        arr2 = draw(st.lists(st.sampled_from(pool), min_size=1, max_size=5))
    elif kind == 3:
        # sorted / reverse sorted, single elements
        arr1 = sorted(draw(st.lists(st.integers(1, 500), min_size=1, max_size=6)))
        arr2 = sorted(draw(st.lists(st.integers(1, 500), min_size=1, max_size=6)), reverse=True)
    else:
        # values built from a shared prefix plus varying suffixes
        base = draw(st.integers(1, 99))
        arr1 = [int(str(base) + str(draw(st.integers(0, 99)))) for _ in range(draw(st.integers(1, 5)))]
        arr2 = [int(str(base) + str(draw(st.integers(0, 999)))) for _ in range(draw(st.integers(1, 5)))]
    return json.dumps(arr1) + "\n" + json.dumps(arr2)

def validate(inp):
    lines = inp.strip().split("\n")
    if len(lines) != 2:
        return False
    try:
        arr1 = json.loads(lines[0])
        arr2 = json.loads(lines[1])
    except Exception:
        return False
    for arr in (arr1, arr2):
        if not isinstance(arr, list):
            return False
        if not (1 <= len(arr) <= 5 * 10**4):
            return False
        for x in arr:
            if type(x) is not int or not (1 <= x <= 10**8):
                return False
    return True

def ref(inp):
    lines = inp.strip().split("\n")
    arr1 = json.loads(lines[0])
    arr2 = json.loads(lines[1])
    best = 0
    for x in arr1:
        sx = str(x)
        for y in arr2:
            sy = str(y)
            k = 0
            while k < len(sx) and k < len(sy) and sx[k] == sy[k]:
                k += 1
            if k > best:
                best = k
    return json.dumps(best)
